INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长组织副本比希尔瓦娜斯组织不死军团还随性，人没齐就开打',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的指挥水平比被诅咒的霜之哀伤还糟糕，团灭了还怪团员操作不行',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的分配系统比奥格瑞玛的下水道还黑，全服就他最能捞金',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的准备时间比巫妖王解冻还慢，团长一上线全团等他半小时',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的指挥风格比被诅咒的黑暗神殿还混乱，南辕北辙指令不清',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的团队管理比被诅咒的冰冠堡垒还混乱，谁说话他都踢，群管都没地位',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的分金系统比被诅咒的艾泽拉斯经济还黑暗，全团就他赚得多',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的副本选择比被诅咒的永夜之塔还盲目，每次都挑最难的打',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我们团长的决策速度比被诅咒的霜之哀伤反应还慢，BOSS都快死了他还在思考',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我憋不住了，我得说，我跟你们说过多少次了，这游戏里啊，有些团长那心黑的啊，跟巫妖王的心一样黑。上次我们打个副本，出个神装，那团长眼疾手快，跟闪电一样，“这装备我拿走了啊”，我寻思你这速度，比希尔瓦娜斯骑着天灾战马还快。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我说你们这些团长啊，组织个副本跟赶集似的。人没齐呢，这都开打了。我寻思这指挥水平，还没巫妖王指挥天灾军团强呢。那巫妖王好歹等小兵都聚齐了再进攻，你们倒好，人没到齐就开始，这不是开玩笑嘛。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我跟你们说啊，我见得黑心团长多了，可没见过像你们这么黑的。上次打副本，那团长指挥起来啊，跟被诅咒的霜之哀伤乱挥似的。南辕北辙，指东打西。我寻思这指挥水平，还不如我家猫。我那猫，还会抓老鼠呢，你们倒好，指挥得全团灭了好几次。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我昨天刚进魔兽世界，看到那个‘开始游戏’的按钮，就跟发现新大陆似的，心里那个激动啊，手都在抖呢！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我第一次进魔兽世界，看到角色创建界面，那各种种族和职业看得我眼花缭乱，半天都没敢点确定，怕选错了。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我刚进魔兽世界的时候，连方向键都找不到，瞎点一通，结果角色一直在原地打转转，旁边有的玩家都看我呢，我脸一下就红了。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我昨天刚进魔兽世界，看到那美丽的游戏画面，我心想这游戏也太好看了吧，结果被路边突然冒出来的怪物吓了一跳，直接把我的小手拿开键盘了。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','你们听说了吗？希尔瓦娜斯和巫妖王在冰冠堡垒那点事儿，整个艾泽拉斯都传遍啦！听说当时巫妖王被围攻，希尔瓦娜娜斯去救援，俩人并肩作战的时候，那眼神交流，电光火石的，现在外头都传他们是“冰冠情侣”了！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我跟你们说，联盟和部落的关系一直很紧张，但是最近听说有些玩家在背后搞事情，竟然让联盟和部落的角色偷偷约会，这不是拱火让两边开战吗！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','听说了吗？瓦里安和吉安娜之间有些小矛盾哦！瓦里安最近在暴风城的会议上总是和吉安娜意见不合，俩人争得面红耳赤的。有次为了联盟的海军战略，瓦里安坚持传统战舰，吉安娜却力挺魔法战舰，僵持了好久才达成共识。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','我听说安度因最近在联盟里很受欢迎呢！不少联盟的女角色都被他的年轻有为和谦逊有礼所吸引，甚至有粉丝团在暴风城为他应援呢！不过他似乎对政治联姻之类的不太感兴趣，更倾向于找一个能和他一起骑马浪迹天涯的伴侣。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','你们知道吗？最近在奥格瑞玛，有传言说沃金和一位德莱尼女性有暧昧关系哦！虽然沃金一直很低调，但据说他们经常一起在酋长帐篷里讨论“部落未来”的计划，而且一讨论就是大半夜。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','听说以色列和哈马斯最近在加沙玩起了\"躲猫猫\"，只不过他们用的不是手绢而是火箭弹！联合国劝架劝得嗓子都哑了，这两边还在比谁的防空警报更响亮，简直像两个较劲的熊孩子！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','俄乌战场上最新潮流：无人机送外卖！乌克兰士兵用改装无人机给前线送披萨，俄罗斯士兵则用它送伏特加。双方默契地不击落送餐无人机，毕竟打仗归打仗，肚子还是要填饱的嘛！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','普京和泽连斯基最近在社交媒体上隔空斗舞！普京发了个跳传统俄罗斯舞的视频，泽连斯基立刻回了个街舞breaking。网友调侃：这比他们在战场上的较量文明多了，建议改舞蹈决胜负！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','加沙地带最新房地产广告：\"防空洞户型，三室一厅带导弹预警系统，学区房（因为学校都在地下），24小时火箭弹景观！\"开发商表示供不应求，这年头安全比豪华重要啊！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','俄军士兵在前线发明了新游戏：\"找北约装备\"！规则简单：谁先找到标有\"Made in NATO\"的乌克兰装备谁就赢。据说最高纪录是一天找到47件，奖品是...被调回后方休整！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','以色列军方推出新兵训练营特别项目：如何在30秒内从烧烤派对冲进防空洞！教官表示这是必备生存技能，毕竟在以色列，火箭弹警报和BBQ烟雾一样常见。毕业生将获得\"最快短跑运动员\"称号！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','乌克兰农民又上头条！这次他们用拖拉机拖走了俄罗斯最先进的防空系统，还附赠一句：\"亲，包邮哦！\"俄罗斯国防部强烈谴责这种\"不道德的农业机械化行为\"。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','加沙地下隧道最新Yelp评价：五星！\"装修简陋但保命，WiFi信号意外地好，就是隔壁哈马斯开会声音有点大。建议自带零食，外卖送不进来。\"一位不愿透露姓名的居民写道。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','俄罗斯征兵处出新规：会玩《使命召唤》的优先录取！军方表示这是\"宝贵的现代战争预训练\"，尤其擅长狙击关卡的直接授予下士军衔。乌克兰回应将举办《战地》电竞大赛选拔人才。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','巴以冲突最新调解方案：Tinder推出\"匹配你的敌人\"特别活动！算法将随机匹配以色列和巴勒斯坦用户聊天。创始人说：\"如果他们先约会再打仗，说不定就打不起来了呢？\"目前已有三对成功约在检查站喝咖啡。',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','听说血色修道院的检察官怀特迈恩和莫格莱尼大领主其实在偷偷约会！每次战斗结束，怀特迈恩复活莫格莱尼时的眼神都特别温柔，有次还被血色十字军的新兵撞见他们在军械库后面牵手！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','暴风城的花园最近总能看到麦迪文和卡德加在月光下散步！虽然麦迪文总是说是在讨论守护者传承的事，但有人看见卡德加偷偷在达拉然买了情侣款法杖！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','奥妮克希亚变成人类形态在暴风城当贵族时，居然和伯瓦尔大公爵有过一段情！有次她不小心在宴会上露出了龙尾巴，伯瓦尔还以为是新款的皮草装饰，还夸她时尚感好！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','伊利丹和玛维其实在暗夜精灵监狱里就互生情愫！那些年的囚禁时光里，玛维每天送饭时都会特意多放一个月亮莓，而伊利丹的牢房墙上全是用指甲刻的玛维侧影！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','萨尔和阿格拉在建立奥格瑞玛时就有感情了！每次部落会议后，萨尔都会用元素之力给阿格拉煮一碗特制岩浆辣汤，说是\"酋长的私人食谱\"，其实是因为知道她喜欢重口味！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','凯尔萨斯在银月城当王子时，其实暗恋过希尔瓦娜斯！他曾经用奥术魔法在逐日者王庭上空放烟花，拼出她的名字，结果魔法失控烧着了三座精灵塔楼！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','罗宁和温蕾萨的初遇其实是个精心设计的局！当时罗宁故意在达拉然图书馆\"不小心\"用奥术飞弹打落她正在拿的书，结果那本书其实是《高等精灵求爱指南》！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','上次在阿拉希盆地，我们队的猎人把照明弹当烟花放，结果对面潜行者集体在战场频道刷\"谢谢老铁送的生日祝福\"！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','战歌峡谷有个战士扛着旗子跳崖，结果被牧师用漂浮术救了，现在联盟和部落都在传\"跳崖能触发隐藏双阵营合作成就\"！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','奥特兰克山谷的NPC骑兵最近罢工了，因为总有玩家把他们当出租车使唤，还抱怨\"这马不能双人同乘差评\"！',0,0);
