INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','远古海滩攻防战时，有个术士把地狱火当冲浪板站在上面，还喊\"部落冲浪俱乐部招新\"！',0,0);
