INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','伊利丹P2阶段有个德鲁伊变旅行形态卡bug卡进蛋刀里，现在公会群里全是\"求代购蛋刀模型手办\"的！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','阿尔法开荒时，有个圣骑士给BOSS上保护祝福，全团笑到灭团，现在DKP系统里多了个\"年度最佳助攻奖\"！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','打奥杜尔钢铁议会，团长喊\"所有人打符文大师\"，结果有个术士全程在给符文大师搓面包，说\"大师饿了怎么打架\"！',0,0);
