INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','打死亡矿井时，有个盗贼把范克里夫叫\"岳父\"，结果全队被小怪追着喊\"彩礼不够别想娶公主\"！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','哀嚎洞穴里，德鲁伊队友突然开始给所有尖牙德鲁伊上动物课，说\"你们的变形术作业不及格\"！',0,0);
