INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','22竞技场有个猎人假死时被对手守尸，结果他宠物在旁边跳踢踏舞，裁判都笑到暂停比赛！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','55队里战士冲锋错人，结果带着四个队友集体跳崖，现在竞技场门口立着\"小心地滑\"的牌子！',0,0);
