INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','达拉然下水道竞技场，有个术士把地狱犬改名\"单身狗\"，结果全场观众都在扔狗粮！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','熔火之心灭团后，有个矮人猎人非要跟管理者埃克索图斯拼酒，现在黑铁酒吧多了个\"火焰领主挑战赛\"！',0,0);
INSERT INTO ai_playerbot_texts (name, text, say_type, reply_type) VALUES ('suggest_something','格鲁尔的巢穴里，有个盗贼对着屠龙者格鲁尔用偷窃技能，居然真摸出个\"龙鳞钱包\"！',0,0);
